from mechanism_design_context import add
add('fava',12,'N','FACT','T','P','misreads_text','wrong_object','imports_neighbour_facts_or_intent',[( 'invented content (fear of the dark)','neighbor','the inventor of stereo sound was afraid of the dark','This detail belongs only to the neighbour.'),('Incorrect entities ("Fourfold Sound")','target','CBS initially planned to name the technology "Fourfold Sound."','The unsupported planned name does occur in target.')],'Mixes a target unsupported name with an invented detail from the neighbour; a planned name differing from actual name is not itself a contradiction.')
add('fava',13,'N','FACT','T','P','misreads_text','consistent','unsupported_target_inference',[( 'states it is unavailable in US pharmacies','target','is it available in pharmacies in the US?','Target asks a question rather than asserting unavailability.'),('asserts it is overseen by the CDC','target','I heard it\'s only used for HIV treatment with the CDC\'s oversight.','The embedded reported claim is checkable and conflicts with supplied FDA/leprosy evidence.')],'Correctly detects the HIV/CDC assertions, but invents an unavailability assertion and mischaracterizes the source nuance; references themselves say unavailable in pharmacies.')
add('fava',14,'N','FACT','T','P','misreads_text','wrong_object','imports_neighbour_facts_or_intent,neighbour_substitutes_for_source_check',[( 'Joaquin Wilde (Michael Paris)','neighbor','Michael Paris, also known as Joaquin Wilde','Reasoning exclusively evaluates the neighbour.'),('is "a member of The Shield."','target','Jay Skillet, aka Jan Kronenberg','Actual target concerns a different wrestler and contains no Shield claim.')],'Entire expressed error concerns the neighbour, substituting for evaluation of the target passage.')
add('fava',15,'N','FACT','T','P','supported','consistent','none_identified',[( 'founding members had a background in environmental activism','target','Its founding members all had a background in environmental activism.','Target makes a specific unsupported universal biography claim.'),('worsened its name','target','renamed the Progressive Mine Workers of America','Source supports a renaming but not the evaluative worsening.')],'The environmental background and evaluative wording are reasonable taxonomy matches. Calling working-conditions focus subjective is imprecise: this is an unsupported factual emphasis rather than necessarily an opinion.')
